#define DT_DRV_COMPAT zephyr_espi_emul

#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/espi.h>
#include <zephyr/drivers/espi_emul.h>
#include <zephyr/sys/util.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(espi_emul, CONFIG_ESPI_LOG_LEVEL);

/**
 * @brief eSPI emulator data
 *
 * @param espi_dev eSPI controller to which emulator is connected
 * @param host_evt_pending_callback Pointer to application callback function
 * @param user_data Pointer to user data
 * @param espi_cb eSPI callback structure for host events
 * @param emul Pointer to the parent emulator structure
 */
struct espi_emul_data {
	const struct device *espi_dev;
	espi_emul_host_evt_sin_cb_t host_evt_pending_callback;
	void *user_data;
	struct espi_callback espi_cb;
	const struct emul *emul;
};

/**
 * @brief eSPI emulator config
 *
 * @param espi_dev eSPI controller to which emulator is connected
 */
struct espi_emul_cfg {
	const struct device *espi_dev;
};

static int espi_emul_send_vw(const struct emul *target,
			    enum espi_vwire_signal signal, uint8_t level)
{
	struct espi_emul_data *data = target->data;

	return espi_emul_driver_api_send_vw(data->espi_dev, signal, level);
}

static int espi_emul_receive_vw(const struct emul *target,
			       enum espi_vwire_signal signal, uint8_t *level)
{
	struct espi_emul_data *data = target->data;

	return espi_emul_driver_api_receive_vw(data->espi_dev, signal, level);
}

static int espi_emul_send_p80(const struct emul *target, uint32_t data)
{
	struct espi_emul_data *emul_data = target->data;

#ifdef CONFIG_ESPI_PERIPHERAL_DEBUG_PORT_80
	return espi_emul_driver_api_send_p80(emul_data->espi_dev, data);
#else
	return -EOPNOTSUPP;
#endif
}

static int espi_emul_read_lpc_request(const struct emul *target,
				     enum lpc_peripheral_opcode *op,
				     uint32_t *addr)
{
	struct espi_emul_data *data = target->data;

	return espi_emul_driver_api_read_lpc_req(data->espi_dev, op, addr);
}

static int espi_emul_write_lpc_response(const struct emul *target,
				       uint32_t data)
{
	struct espi_emul_data *emul_data = target->data;

	return espi_emul_driver_api_write_lpc_com(emul_data->espi_dev, data);
}

static int espi_emul_set_host_evt_sin_cb(const struct emul *target,
					espi_emul_host_evt_sin_cb_t cb,
					void *user_data)
{
	struct espi_emul_data *data = target->data;

	data->host_evt_pending_callback = cb;
	data->user_data = user_data;

	return 0;
}

static void espi_emul_host_evt_rx_isr(const struct device *dev,
				     struct espi_callback *cb,
				     struct espi_event event)
{
	struct espi_emul_data *data = CONTAINER_OF(cb, struct espi_emul_data, espi_cb);
	const struct emul *target = data->emul;

	if (data->host_evt_pending_callback) {
		data->host_evt_pending_callback(target, event, data->user_data);
	}
}

static int espi_emul_init(const struct emul *target)
{
	const struct espi_emul_cfg *cfg = target->cfg;
	struct espi_emul_data *data = target->data;

	data->emul = target;
	data->espi_dev = cfg->espi_dev;

	data->espi_cb.handler = espi_emul_host_evt_rx_isr;
	data->espi_cb.evt_mask = ESPI_EVENT_HOST_RST_assert |
			   ESPI_EVENT_HOST_RST_deassert;

	espi_init_callback(data->espi_dev, &data->espi_cb, data->espi_cb.evt_mask);
	espi_add_callback(data->espi_dev, &data->espi_cb);

	return 0;
}

static const struct espi_emul_api espi_emul_api = {
	.send_vw = espi_emul_send_vw,
	.receive_vw = espi_emul_receive_vw,
	.send_p80 = espi_emul_send_p80,
	.read_lpc_request = espi_emul_read_lpc_request,
	.write_lpc_response = espi_emul_write_lpc_response,
	.set_host_evt_sin_cb = espi_emul_set_host_evt_sin_cb,
};

#define ESPI_EMUL_INIT_FN(n)                                                   \
	BUILD_ASSERT(DT_NODE_HAS_STATUS(DT_INST_BUS(n), okay),                 \
		     "eSPI emulator parent eSPI controller is disabled");      \
									       \
	static struct espi_emul_data espi_emul_data_##n;                       \
									       \
	static const struct espi_emul_cfg espi_emul_cfg_##n = {                \
		.espi_dev = DEVICE_DT_GET(DT_INST_BUS(n)),                     \
	};                                                                     \
									       \
	EMUL_DT_INST_DEFINE(n, espi_emul_init, &espi_emul_data_##n,             \
			    &espi_emul_cfg_##n, &espi_emul_api, NULL);

DT_INST_FOREACH_STATUS_OKAY(ESPI_EMUL_INIT_FN)
